#include "ViewerRuntime.h"
#include "V048Features.h"
#include <regex>
namespace {
bool ValidGroup(const std::wstring& id){static const std::wregex re(LR"(^grp_[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$)");return std::regex_match(id,re);}
std::wstring Canonical(std::wstring text){std::transform(text.begin(),text.end(),text.begin(),towlower);return text;}
}
std::vector<std::wstring> GroupIds(const std::wstring& tags){std::wistringstream stream(tags);std::wstring line;std::vector<std::wstring> ids;while(std::getline(stream,line)){auto a=line.find_first_not_of(L" \t\r"),b=line.find_last_not_of(L" \t\r");if(a==line.npos)continue;line=line.substr(a,b-a+1);const std::wstring prefix=L"【グループID】";if(line.find(prefix)!=0)continue;auto id=line.substr(prefix.size());if(ValidGroup(id)){id=Canonical(id);if(std::find(ids.begin(),ids.end(),id)==ids.end())ids.push_back(id);}}return ids;}
std::wstring GroupUrl(const std::wstring& id){return ValidGroup(id)?L"https://vrchat.com/home/group/"+Canonical(id):L"";}
MetadataEdit BuildAutomaticEdit(const EditableMetadata& existing,const stage3::Record& record,const stage3::Config& config){
    MetadataEdit edit;edit.stage3Xml=stage3::RecordXml(record,config.saveUserIds);
    static const std::wregex worldId(LR"(^wrld_[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$)");bool consistent=std::regex_match(record.world,worldId)&&(existing.values[3].empty()||existing.values[3]==record.world);
    if(consistent){if(existing.values[2].empty()&&!record.worldName.empty()){edit.actions[2]=EditAction::Set;edit.values[2]=record.worldName;}if(existing.values[3].empty()&&!record.world.empty()){edit.actions[3]=EditAction::Set;edit.values[3]=record.world;}}
    if(config.saveGroupIds&&ValidGroup(record.group)){auto ids=GroupIds(existing.values[5]);auto id=Canonical(record.group);if(std::find(ids.begin(),ids.end(),id)==ids.end()){edit.actions[5]=EditAction::Append;edit.values[5]=L"【グループID】"+id;}}
    return edit;
}
void RunV048Tests(const fs::path& folder,std::ostream& report){
    auto require=[&](bool ok,const char* label){if(!ok)throw std::runtime_error(label);report<<"PASS: "<<label<<'\n';};
    const std::wstring group=L"grp_12345678-abcd-1234-abcd-123456789abc";stage3::Event event;stage3::InstanceTimeline timeline;
    require(stage3::ParseLogLine(L"2026.10.10 12:00:00 Log - [Behaviour] Joining or Creating Room: 名前 & テスト",event)&&event.kind==stage3::Kind::RoomName&&event.worldName==L"名前 & テスト","v0.4.8 world name log parse");timeline.Add(event);
    require(stage3::ParseLogLine(L"2026.10.10 12:00:01 Log - [Behaviour] Joining wrld_test:123~group("+group+L")~groupAccessType(public)",event)&&event.group==group,"v0.4.8 group instance ID parse");timeline.Add(event);auto snapshot=timeline.At(stage3::ParseTime(L"2026.10.10 12:00:04"));require(snapshot.worldName==L"名前 & テスト"&&snapshot.group==group,"v0.4.8 adjacent world name and ID paired");
    stage3::InstanceTimeline reverse;stage3::ParseLogLine(L"2026.10.10 12:01:00 Log - [Behaviour] Joining wrld_second:123",event);reverse.Add(event);stage3::ParseLogLine(L"2026.10.10 12:01:01 Log - [Behaviour] Joining or Creating Room: Reverse",event);reverse.Add(event);require(reverse.At(stage3::ParseTime(L"2026.10.10 12:01:04")).worldName==L"Reverse","v0.4.8 reversed adjacent name pairing");
    stage3::ParseLogLine(L"2026.10.10 12:00:05 Log - [Behaviour] Joining wrld_next:456",event);timeline.Add(event);require(timeline.At(stage3::ParseTime(L"2026.10.10 12:00:08")).worldName.empty()&&timeline.At(stage3::ParseTime(L"2026.10.10 12:00:08")).group.empty(),"v0.4.8 room boundary clears old name and group");
    stage3::InstanceTimeline boundary;stage3::ParseLogLine(L"2026.10.10 12:02:00 Log - [Behaviour] Joining wrld_old:123",event);boundary.Add(event);stage3::ParseLogLine(L"2026.10.10 12:02:01 Log - [Behaviour] Joining or Creating Room: New room",event);boundary.Add(event);stage3::ParseLogLine(L"2026.10.10 12:02:02 Log - [Behaviour] Joining wrld_new:456",event);boundary.Add(event);require(boundary.At(stage3::ParseTime(L"2026.10.10 12:02:00")).worldName.empty()&&boundary.At(stage3::ParseTime(L"2026.10.10 12:02:05")).worldName.empty(),"v0.4.8 name between two nearby room boundaries is withheld");
    stage3::InstanceTimeline late;stage3::ParseLogLine(L"2026.10.10 12:03:00 Log - [Behaviour] Joining wrld_late:123",event);late.Add(event);stage3::ParseLogLine(L"2026.10.10 12:03:05 Log - [Behaviour] Joining or Creating Room: Too late",event);late.Add(event);require(late.At(stage3::ParseTime(L"2026.10.10 12:03:08")).worldName.empty(),"v0.4.8 distant unpaired name held");
    stage3::Record record;record.world=L"wrld_12345678-abcd-1234-abcd-123456789abc";record.worldName=L"名前 & テスト";record.group=group;record.members={{L"Person",L"usr_private"}};stage3::Candidate candidate;candidate.person=record.members[0];record.candidates={candidate};stage3::Config config;EditableMetadata existing;
    auto edit=BuildAutomaticEdit(existing,record,config);require(edit.actions[2]==EditAction::Set&&edit.actions[3]==EditAction::Set&&edit.actions[5]==EditAction::Append&&edit.stage3Xml.find("UserId")==edit.stage3Xml.npos&&edit.stage3Xml.find("usr_private")==edit.stage3Xml.npos,"v0.4.8 defaults fill world/tag and omit user IDs");
    existing.values[2]=L"Existing";existing.values[3]=record.world;existing.values[5]=L"Other\n【グループID】"+group;auto retained=BuildAutomaticEdit(existing,record,config);require(retained.actions[2]==EditAction::Keep&&retained.actions[3]==EditAction::Keep&&retained.actions[5]==EditAction::Keep,"v0.4.8 existing world and duplicate group tag preserved");existing.values[2].clear();existing.values[3]=L"wrld_conflict";retained=BuildAutomaticEdit(existing,record,config);require(retained.actions[2]==EditAction::Keep&&retained.actions[3]==EditAction::Keep,"v0.4.8 ID conflict prevents wrong name fill");
    config.saveUserIds=true;config.saveGroupIds=false;existing.values={};auto enabled=BuildAutomaticEdit(existing,record,config);require(enabled.stage3Xml.find("usr_private")!=enabled.stage3Xml.npos&&enabled.actions[5]==EditAction::Keep,"v0.4.8 user ID ON and group ID OFF");
    auto rawOff=stage3::RecordXml(record,false);XmpFields offFields;std::wstring error;require(ParseXmp(rawOff,offFields,error)&&offFields.members==L"Person"&&offFields.candidates==L"Person"&&offFields.recordReference.find(L"usr_private")==std::wstring::npos,"v0.4.8 names remain when user IDs disabled");
    auto ids=GroupIds(L"【グループID】"+group+L"\n【グループID】"+group+L"\n【グループID】javascript:bad\n");require(ids.size()==1&&GroupUrl(ids[0])==L"https://vrchat.com/home/group/"+group&&GroupUrl(L"../evil").empty(),"v0.4.8 group links validate IDs and deduplicate");
    config.saveGroupIds=true;auto target=folder/L"v048-record.png";fs::remove(target);existing=InspectEditable((folder/L"writer-alpha.png").wstring());auto combined=BuildAutomaticEdit(existing,record,config);SaveMetadataCopy((folder/L"writer-alpha.png").wstring(),target.wstring(),existing.fingerprint,combined);auto read=InspectEditable(target.wstring());require(read.values[2]==record.worldName&&read.values[3]==record.world&&read.recordReference.find(L"Person")!=std::wstring::npos&&read.recordReference.find(L"usr_private")!=std::wstring::npos&&GroupIds(read.values[5]).size()==1,"v0.4.8 saved world fields and read-only record reference");MetadataEdit manual;manual.actions[1]=EditAction::Set;manual.values[1]=L"Updated author";auto changed=folder/L"v048-edited-reference.png";fs::remove(changed);SaveMetadataCopy(target.wstring(),changed.wstring(),read.fingerprint,manual);auto after=InspectEditable(changed.wstring());require(after.recordReference==read.recordReference&&after.values[5]==read.values[5],"v0.4.8 manual edit preserves previously recorded user IDs and group tags");
}
